import{_ as t,o,c as a,a5 as n}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"Brand-Grounded RAG Captions, Editor AI Popover, Content Humanizer & Text Safety Moderation","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/05-ai-rag-and-crawler/rag-caption-moderation-and-humanizer/spec.md","filePath":"feature/modules/05-ai-rag-and-crawler/rag-caption-moderation-and-humanizer/spec.md"}'),r={name:"feature/modules/05-ai-rag-and-crawler/rag-caption-moderation-and-humanizer/spec.md"};function i(d,e,c,s,l,p){return o(),a("div",null,[...e[0]||(e[0]=[n('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="brand-grounded-rag-captions-editor-ai-popover-content-humanizer-text-safety-moderation" tabindex="-1">Brand-Grounded RAG Captions, Editor AI Popover, Content Humanizer &amp; Text Safety Moderation <a class="header-anchor" href="#brand-grounded-rag-captions-editor-ai-popover-content-humanizer-text-safety-moderation" aria-label="Permalink to &quot;Brand-Grounded RAG Captions, Editor AI Popover, Content Humanizer &amp; Text Safety Moderation&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>rag-caption-moderation-and-humanizer</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>05-ai-rag-and-crawler</code> — AI Trend Crawler, Neo4j Knowledge Graph &amp; Brand RAG</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Admin</code></td></tr><tr><td style="text-align:left;"><strong>Consolidated Feature Scopes</strong></td><td style="text-align:left;"><code>brand-trend-caption-quality</code>, <code>caption-credit-request</code>, <code>caption-neo4j-context</code>, <code>caption-text-moderation</code>, <code>caption-trend-retrieval</code>, <code>content-humanizer</code>, <code>editor-ai-content-popover</code></td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/06-ai-features/3-7-6-generate-caption/spec.html">FR 3.7.6 — Generate Caption</a> · <a href="./../../../srs/09-admin-functions/3-10-4-content-moderation-queue/spec.html">FR 3.10.4 — Content Moderation Queue</a></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Unify the complete AI text authoring and safety pipeline inside the Task &amp; Post Editor: <strong>ChromaDB Brand RAG + Neo4j Trend Retrieval</strong> (<code>caption-trend-retrieval</code>, <code>caption-neo4j-context</code>, <code>brand-trend-caption-quality</code>), <strong>Anti-AI-Slop Content Humanizer</strong> (<code>content-humanizer</code>), <strong>Inline Editor AI Content Popover</strong> (<code>editor-ai-content-popover</code>), <strong>Idempotent Credit Accounting</strong> (<code>caption-credit-request</code>), and <strong>Automated Text Compliance Moderation</strong> (<code>caption-text-moderation</code> -&gt; <code>InternalModerationController</code>).</p><h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>As a <code>Creator</code>, <code>Manager</code>, or <code>Owner</code>, I want AI captions generated or refined inside the Editor popover to sound natural and human (<code>humanizer.py</code>), stay strictly faithful to uploaded Brand Guidelines and Neo4j trend context, and pass automated community-safety moderation before submission or publishing.</li></ul><h2 id="_3-consolidated-acceptance-criteria" tabindex="-1">3. Consolidated Acceptance Criteria <a class="header-anchor" href="#_3-consolidated-acceptance-criteria" aria-label="Permalink to &quot;3. Consolidated Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Dual ChromaDB + Neo4j Grounding (<code>caption-trend-retrieval</code>, <code>caption-neo4j-context</code>, <code>brand-trend-caption-quality</code>):</strong> <code>llm_service.py</code> + <code>prompt_builder.py</code> inject top-scoring <code>brand_docs_{workspace_id}</code> chunks (strictly forbidding invented prices, phone numbers, or warranties) alongside Neo4j trend neighborhood entities/angles so captions connect the trend naturally to the brand.</li><li><strong>Content Humanizer (<code>content-humanizer</code>):</strong> <code>app/utils/humanizer.py</code> strips robotic LLM clichés, forced triads, repetitive dash patterns, and artificial sales hype across both Vietnamese and English outputs during generate, <code>/captions/refine</code>, and <code>/captions/adapt</code>.</li><li><strong>Editor AI Content Popover &amp; Choice Tracking (<code>editor-ai-content-popover</code>, <code>caption-credit-request</code>):</strong> Inline Editor AI popover (<code>ContentCreatorAiPanel.tsx</code>, <code>AIGeneratePanel.tsx</code>, <code>AiCaptionDialog.tsx</code>) attaches <code>Idempotency-Key</code> + <code>X-AI-Workspace-Id</code>, records selected variant via <code>POST /captions/{generationId}/choice</code>, and persists accepted copy into Task Content Versions (<code>task_content_snapshots</code>).</li><li><strong>Automated Text Moderation (<code>caption-text-moderation</code>):</strong> <code>POST /api/v1/workspaces/{workspaceId}/ai/captions/moderate</code> (<code>text_moderation_service.py</code>) evaluates drafts against profanity, violence, hate speech, and platform safety rules, displaying <code>CaptionModeration.tsx</code> / <code>EditorModerationStatus.tsx</code> badges and forwarding severe flags to <code>InternalModerationController</code> (<code>/api/v1/internal/moderation/flags</code>) for FR 3.10.4 review.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Every user-facing string, tooltip, dialog prompt, status badge, and error banner uses key-parallel translations (<code>editor.aiPopover.*</code>, <code>editor.aiCaption.*</code>, <code>editor.humanizer.*</code>, <code>editor.moderation.*</code> in <code>src/i18n/locales/{vi,en}/editor.json</code>) on <code>brandhub-web</code> and <code>tr()</code> (<code>en.json</code> + <code>vi/common.json</code>) on <code>brandhub-mobile-app</code> with zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces, drawers, badges, charts, and interactive controls use semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useAppPreferences().palette</code> tokens on Mobile, achieving WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-surfaces-lifecycle-states" tabindex="-1">4. UI / UX Surfaces &amp; Lifecycle States <a class="header-anchor" href="#_4-ui-ux-surfaces-lifecycle-states" aria-label="Permalink to &quot;4. UI / UX Surfaces &amp; Lifecycle States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>components/ai/AiCaptionDialog.tsx</code>, <code>pages/editor/components/{AIGeneratePanel,ContentCreatorAiPanel,CaptionModeration,EditorModerationStatus}.tsx</code></li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/more/{AiCaptionScreen,AiPostStudioScreen}.tsx</code>, <code>src/utils/editorModeration.ts</code> (<code>editorModeration.test.ts</code>)</li><li><strong>UI States:</strong><ul><li><strong>Loading / Streaming:</strong> Deterministic skeleton placeholders, progress bars, and disabled submit buttons preventing duplicate requests.</li><li><strong>Empty / Onboarding:</strong> Contextual empty state with localized call-to-action and zero fabricated mock fallback data.</li><li><strong>Active / Realtime Sync:</strong> Scoped <code>TanStack Query</code> cache updates + WebSocket/SSE/polling synchronization where applicable.</li><li><strong>Error / Conflict Recovery:</strong> Actionable localized error banners (<code>400/403/404/409/429/503</code>) preserving unsaved user input.</li></ul></li></ul><h2 id="_5-api-messaging-protocol-contract" tabindex="-1">5. API, Messaging &amp; Protocol Contract <a class="header-anchor" href="#_5-api-messaging-protocol-contract" aria-label="Permalink to &quot;5. API, Messaging &amp; Protocol Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route / Channel / Filter</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service &amp; Handler</th></tr></thead><tbody><tr><td style="text-align:left;">`POST /api/v1/workspaces/{workspaceId}/ai/captions[/refine</td><td style="text-align:left;">/adapt]`</td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>) + <code>Idempotency-Key</code></td></tr><tr><td style="text-align:left;"><code>POST /api/v1/workspaces/{workspaceId}/ai/captions/{generationId}/choice</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td><td style="text-align:left;"><code>AiCaptionController</code> -&gt; records chosen variant without credit charge</td></tr><tr><td style="text-align:left;"><code>POST /api/v1/workspaces/{workspaceId}/ai/captions/moderate</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td><td style="text-align:left;"><code>AiCaptionController</code> -&gt; <code>text_moderation_service.py</code> compliance check</td></tr><tr><td style="text-align:left;"><code>POST /api/v1/internal/moderation/flags</code></td><td style="text-align:left;"><code>X-Internal-Service-Key</code></td><td style="text-align:left;"><code>InternalModerationController</code> -&gt; enqueues flagged items into <code>content_moderation_reviews</code></td></tr></tbody></table><h2 id="_6-error-handling-security-edge-cases" tabindex="-1">6. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-security-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Prompt Injection in User Topic or Trend Post:</strong> Untrusted trend snippets and user notes are delimited inside data blocks and stripped of system-override directives before LLM invocation.</li><li><strong>Retry with Identical <code>Idempotency-Key</code>:</strong> Replays stored <code>ai_caption_generations</code> output without re-invoking Groq/Gemini.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Aligned SRS Functional Requirements:</strong> <a href="./../../../srs/06-ai-features/3-7-6-generate-caption/spec.html">FR 3.7.6 — Generate Caption</a> · <a href="./../../../srs/09-admin-functions/3-10-4-content-moderation-queue/spec.html">FR 3.10.4 — Content Moderation Queue</a></li><li><strong>BA &amp; Architecture References:</strong> <a href="./../../../../ba/06-ai-features.html">BA 06 AI Features</a> · <a href="./../../../../ba/09-admin-functions.html">BA 09 Admin Functions</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Production code verified across backend, AI/publisher workers, Web, and Mobile; <code>vi.json</code> + <code>en.json</code> parity verified; Light/Dark mode audited; all automated verification suites in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> De-scoped SRS items (livestream features, subscription plan downgrades, PayOS/VNPay/Stripe gateways, Zalo OA publishing, or copyright/plagiarism scanning).</li></ul>',19)])])}const h=t(r,[["render",i]]);export{u as __pageData,h as default};
